sp_widget.client_script:
api.controller=function($location) {
    var c = this;

    c.toggleView = function(row) {
        row.expanded = !row.expanded;
    };

    c.goToFeedback = function(row) {
        $location.path('/student_feedback').search('ticket', row.sysId);
    };
}

sp_widget.css:
/* =========================================================
   MEALCARE — STUDENT DASHBOARD SIDEBAR
   Professional Dark Frame Theme
   Styling only — HTML / JS unchanged
   ========================================================= */

/* Main Student Sidebar */

.student-sidebar {
  background: #1E293B !important;
  color: #F8FAFC;
  border-right: 1px solid #334155;
}


/* =========================================================
   STUDENT ROLE ICON
   ========================================================= */

.student-sidebar .sidebar-icon,
.student-sidebar .role-icon,
.student-sidebar .student-icon {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  background: #2563EB;
  color: #FFFFFF;

  border-radius: 50%;

  font-size: 18px;
  font-weight: 700;

  border: 2px solid #60A5FA;

  box-shadow:
    0 6px 16px rgba(37, 99, 235, 0.30);

  flex-shrink: 0;
}


/* =========================================================
   SIDEBAR ROLE / PORTAL TEXT
   ========================================================= */

.student-sidebar .sidebar-title,
.student-sidebar .role-name,
.student-sidebar .portal-title {
  color: #FFFFFF;
}

.student-sidebar .sidebar-subtitle,
.student-sidebar .role-label,
.student-sidebar .portal-subtitle {
  color: #94A3B8;
}


/* =========================================================
   SIDEBAR NAVIGATION
   ========================================================= */

.student-sidebar a,
.student-sidebar button {
  color: #CBD5E1;
}

.student-sidebar a:hover,
.student-sidebar button:hover {
  background: #334155;
  color: #FFFFFF;
}


/* =========================================================
   ACTIVE SIDEBAR ITEM
   ========================================================= */

.student-sidebar .active,
.student-sidebar .active-section,
.student-sidebar a.active {
  background: #2563EB;
  color: #FFFFFF;

  border-radius: 10px;
}


/* =========================================================
   SIDEBAR ICONS
   ========================================================= */

.student-sidebar .nav-icon,
.student-sidebar .menu-icon {
  color: #94A3B8;
}

.student-sidebar .active .nav-icon,
.student-sidebar .active .menu-icon {
  color: #FFFFFF;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 767px) {

  .student-sidebar .sidebar-icon,
  .student-sidebar .role-icon,
  .student-sidebar .student-icon {
    width: 38px;
    height: 38px;
    font-size: 16px;
  }

}

sp_widget.script:
(function() {

    var user = gs.getUser();
    data.userName = user.getDisplayName();

    // Priority choice value → CSS class (matches real choice values: 1=Critical, 2=High, 3=Medium, 4=Low)
    var priorityClassMap = {'1':'critical', '2':'high', '3':'medium', '4':'low'};

    var fc = new GlideRecord('x_snc_campus_foo_1_food_complaint');
    fc.addQuery('student.user', gs.getUserID());
    fc.orderByDesc('opened_at');
    fc.query();

    data.requests = [];
    var total = 0, active = 0, resolved = 0, feedbackEligible = 0;

    while (fc.next()) {
        total++;

        var state = fc.state.toString();
        if (state == 'resolved') {
            resolved++;
        } else {
            active++;
        }

        var isFbEligible = (fc.feedback_eligible == true);
        if (isFbEligible) {
            feedbackEligible++;
        }

        data.requests.push({
            sysId: fc.getUniqueValue(),
            number: fc.number.toString(),
            useCase: fc.use_case.getDisplayValue(),
            messHall: fc.mess_hall.getDisplayValue(),
            mealType: fc.meal_type.getDisplayValue(),
            priority: fc.priority.getDisplayValue() || 'Not set',
            priorityClass: priorityClassMap[fc.priority.toString()] || 'medium',
            state: fc.state.getDisplayValue(),
            stateClass: state,
            openedAt: fc.opened_at.getDisplayValue(),
            description: fc.description.toString(),
            resolutionNotes: fc.resolution_notes ? fc.resolution_notes.toString() : '',
            feedbackEligible: isFbEligible,
            expanded: false
        });
    }

    data.kpi = {
        total: total,
        active: active,
        resolved: resolved,
        feedbackEligible: feedbackEligible
    };

})();
